583	\section{Generalized Pauli observables}
584	% Paper label sec:generalized-pauli kept for cross-reference fidelity.
585	\label{sec:generalized-pauli}
586	
587	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
588		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
589		\lean{MIPStarRE.QPBT.primeTauObservable}
590		\uses{def:subfield-trace, def:lin-reg}
591		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
592		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
593		\begin{equation}\label{eq:pauli-fp}
594			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
595			\qquad \text{and} \qquad
596			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
597		\end{equation}
598		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
599		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
600		$\C^{\F_q}$
601		\[
602			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
603			\qquad \text{and} \qquad
604			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
605		\]
606		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
607		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
608		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
609		signs. All the $\tau^X$ operators commute with one another, as do all the
610		$\tau^Z$ operators. Their common eigenbases consist of the vectors
611		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
612		\[
613			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
614			\omega^{-\tr(ej)} \ket{j}\;, \qquad
615			\ket{e_Z} = \ket{e}\;;
616		\]
617		the Fourier transform
618		\begin{equation}\label{eq:fourier-f}
619			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
620			\omega^{-\tr(ab)} \ket{a}\bra{b}
621		\end{equation}
622		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
623		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
624		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
625		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
626		\[
627			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
628			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
629		\]
630		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
631		The distinction between the general prime-characteristic definitions and
632		the characteristic-two specializations used by the Pauli basis test is
